from taf.rfrl.l3_call.connection.api_connection.classical_api_connection import EnbApiConnection
from taf.rfrl.l3_call.connection.api_connection.classical_api_connection import GnbApiConnection
from taf.rfrl.l3_call.connection.api_connection.cloud_api_connection import CloudApiConnection
from taf.rfrl.l3_call.connection.exceptions import InvalidNodeType, InvalidRan


class ApiConnectionFactory:
    """
    Creates EnbConnection or GncConnection instances
    """

    @staticmethod
    def create_connection(ran, node):
        """
        Creates either EnbConnection or GnbConnection instance
        depending on ran and node

        :param ran: RAN type: cloud/classical
        :type ran: str
        :param node: Node for which admin API connection is needed: enb/gnb
        :type node: str
        :return: EnbConnection or GnbConnection instance
        :rtype: Connection

        :raises: InvalidNodeType: if given node is neither gnb nor enb
        """
        if ran == "cloud":
            return CloudApiConnection()

        elif ran == "classical":
            if node.lower() == "gnb":
                return GnbApiConnection()
            if node.lower() == 'enb':
                return EnbApiConnection()
            else:
                raise InvalidNodeType("Node type for classical RAN must be either gnb or enb!")

        else:
            raise InvalidRan("RAN must be either cloud or classical!")
